import json
import csv
import io


def handler(event):
    """
    Convert JSON array to CSV string.

    Input:
        - data: JSON array of objects (required)
        - columns: Optional list of columns to include (in order)
        - delimiter: Optional delimiter character (default: comma)
        - include_header: Whether to include header row (default: true)
        - null_value: Value to use for null values (default: empty string)

    Returns:
        - csv: CSV string
        - row_count: Number of data rows
        - column_count: Number of columns
    """
    # Parse input
    if isinstance(event, dict):
        data = event.get("data", [])
        columns = event.get("columns", None)
        delimiter = event.get("delimiter", ",")
        include_header = event.get("include_header", True)
        null_value = event.get("null_value", "")
    else:
        # Try parsing as JSON if string
        try:
            parsed = json.loads(str(event))
            if isinstance(parsed, dict):
                data = parsed.get("data", [])
                columns = parsed.get("columns", None)
                delimiter = parsed.get("delimiter", ",")
                include_header = parsed.get("include_header", True)
                null_value = parsed.get("null_value", "")
            else:
                data = parsed
                columns = None
                delimiter = ","
                include_header = True
                null_value = ""
        except:
            return {
                "ok": False,
                "error": "Invalid input. Expected JSON array or object with data field."
            }

    # Validate input
    if not isinstance(data, list):
        return {
            "ok": False,
            "error": "Input data must be an array of objects"
        }

    if len(data) == 0:
        return {
            "ok": True,
            "csv": "",
            "row_count": 0,
            "column_count": 0
        }

    # Determine columns from first object if not specified
    if columns is None:
        first_item = data[0]
        if isinstance(first_item, dict):
            columns = list(first_item.keys())
        else:
            return {
                "ok": False,
                "error": "Data must be an array of objects"
            }

    # Validate all items
    for i, item in enumerate(data):
        if not isinstance(item, dict):
            return {
                "ok": False,
                "error": f"Item at index {i} is not an object"
            }
        for col in columns:
            if col not in item:
                return {
                    "ok": False,
                    "error": f"Column {col} not found in item at index {i}"
                }

    # Build CSV
    output = io.StringIO()
    writer = csv.writer(output, delimiter=delimiter)

    if include_header:
        writer.writerow(columns)

    for item in data:
        row = []
        for col in columns:
            value = item.get(col)
            if value is None:
                row.append(null_value)
            elif isinstance(value, (dict, list)):
                row.append(json.dumps(value))
            else:
                row.append(str(value))
        writer.writerow(row)

    csv_string = output.getvalue()

    return {
        "ok": True,
        "csv": csv_string,
        "row_count": len(data),
        "column_count": len(columns)
    }
